(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zo-sj-prepa-ped-j4-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zo-sj-prepa-ped-j4-idesfm\",\n \"titre\": \"Préparation D.E (J) · J4 Pédiatrie IDE/SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 60,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n   \"sha256\": \"45110ca169c7b815e8c5983cb6aa915440763cce1306bb015109584afb42df7f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Pédiatrie · Prépa D.E J4 (IDE/SFM)\",\n     \"slug\": \"prepa-ped-j4-idesfm\",\n     \"pages\": \"\",\n     \"count\": 60,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Pédiatrie\",\n     \"source\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La PCIMNE recherche systématiquement les signes généraux de danger chez l'enfant malade\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La première étape de l'évaluation PCIMNE est la recherche des 5 signes généraux de danger : vomit tout, incapable de boire ou de téter, antécédents de convulsions, convulsions actuelles, léthargique ou inconscient.\\n\\nSource : Cours PCIMNE 2026, Signes généraux de dangers ; Procédure de prise en charge (Évaluer l'enfant malade)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La PCIMNE recommande de classer la maladie de l'enfant avant de choisir le traitement adapté\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La procédure PCIMNE suit l'ordre : évaluer, classer la maladie, choisir le traitement, traiter, conseiller la mère, assurer le suivi.\\n\\nSource : Cours PCIMNE 2026, Procédure de la prise en charge de l'enfant malade\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une diarrhée aiguë évolue depuis moins de 14 jours\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La diarrhée aiguë dure moins de 14 jours ; au-delà, c'est une diarrhée persistante.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Introduction (Définition et limite du thème)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le plan B est indiqué chez un enfant présentant une déshydratation sévère\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le plan B traite les signes évidents de déshydratation (SRO 75 ml/kg en 4 heures). La déshydratation sévère relève du plan C (réhydratation par voie veineuse à l'hôpital).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Diagnostic de gravité (Tableau n°1) ; Rôles curatifs (Plans B et C)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pendant une diarrhée, il faut interrompre l'allaitement maternel.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Il faut au contraire allaiter plus souvent et plus longtemps et continuer l'alimentation pour prévenir la malnutrition.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, Plan A : donner davantage de liquides ; L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Rôles curatifs (Alimentation)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La prise en charge de la malnutrition aiguë sévère avec complications nécessite une hospitalisation dans une structure adaptée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La malnutrition aiguë sévère avec complications (anorexie, infection, hypothermie, déshydratation…) est orientée vers une unité de nutrition thérapeutique à l'hôpital.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Malnutrition de l'enfant — Diagnostic anthropométrique (Classification de la malnutrition aiguë sévère)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La présence de sang visible dans les selles oriente vers une dysenterie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La dysenterie est l'émission de selles glaireuses et sanglantes.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Introduction (Définition et limite du thème)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une malnutrition aiguë sévère peut être diagnostiquée en présence d'œdèmes nutritionnels bilatéraux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les œdèmes bilatéraux suffisent à classer l'enfant en malnutrition aiguë sévère, même si le périmètre brachial ou le rapport poids/taille sont normaux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Malnutrition de l'enfant — Diagnostic anthropométrique (Classification de la malnutrition aiguë sévère)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La surveillance de la croissance de l'enfant repose notamment sur le suivi régulier du poids et de la taille\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les mensurations (poids, taille, périmètre crânien, périmètre brachial) permettent de suivre la croissance et l'état nutritionnel de l'enfant.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Mensurations — Introduction (Définition)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'éruption dentaire est un indicateur de croissance qualitative chez l'enfant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La croissance quantitative (somatique) se mesure par le poids, la taille et les périmètres. L'éruption dentaire est une étape de maturation, donc un indicateur qualitatif. Remarque : Le classement de l'éruption dentaire comme indicateur qualitatif n'est pas écrit mot à mot dans les cours.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Mensurations — Introduction (Définition de la croissance quantitative)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la démarche de soins, les données de dépendance permettent d'identifier les besoins perturbés de l'enfant.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'analyse des données d'indépendance et de dépendance permet de poser le diagnostic infirmier et d'identifier les besoins fondamentaux non satisfaits.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Introduction au raisonnement clinique — Diagnostic infirmier (Analyse et interprétation des données)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'allaitement maternel exclusif autorise l'administration quotidienne d'eau potable au nourrisson\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'allaitement exclusif consiste à ne donner que le lait maternel, sans eau, décoction, jus ni autre aliment, à l'exception des médicaments prescrits.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Allaitement — Définitions (Allaitement exclusif) ; L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Introduction\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La prolactine stimule principalement la production du lait maternel\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La prolactine, sécrétée par l'antéhypophyse sous l'effet de la succion, commande la production du lait.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Physiologie de la lactation (Production du lait)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'administration d'un traitement prescrit constitue systématiquement un soin relevant du rôle propre infirmier.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un traitement prescrit est exécuté sur instruction du médecin : c'est un soin délégué, pas un soin propre.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Introduction au raisonnement clinique — Plan de soins (Interventions : soins délégués / soins propres)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La vitamine K administrée au nouveau-né contribue à prévenir les saignements liés au déficit en vitamine K\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'injection systématique de vitamine K1 à la naissance prévient la maladie hémorragique du nouveau-né, due à un déficit en vitamine K.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Maladie hémorragique du nouveau-né — Rôles de soins (Après la naissance)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un enfant né à 35 semaines d'aménorrhée est un nouveau-né à terme\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le nouveau-né à terme naît entre 37 et 41 SA + 6 jours. À 35 SA, c'est un prématuré (22 à 36 SA + 6 jours).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Nouveau-né normal — Introduction (Définition) ; Nouveau-né prématuré — Introduction\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La respiration et la température font partie de la surveillance initiale du nouveau-né\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dès la naissance, on vérifie la respiration et on prévient l'hypothermie ; la température est mesurée toutes les 15 minutes pendant la première heure.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Soins essentiels aux nouveau-nés — Technique de soins (0-60 minutes)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lors d'une crise convulsive, la priorité est de protéger l'enfant contre les traumatismes et de surveiller sa respiration.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"À l'accueil, il faut installer l'enfant en position de sécurité, assurer la liberté des voies aériennes et l'oxygéner si besoin, puis arrêter la crise.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Convulsions de l'enfant — Diagnostic (Accueil de l'enfant aux urgences)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pendant une convulsion, il faut introduire un objet entre les dents de l'enfant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Introduire un objet dans la bouche est dangereux (blessures, dents cassées, obstruction des voies aériennes). On protège l'enfant et on libère ses voies aériennes. Remarque : L'interdiction d'introduire un objet n'est pas écrite mot à mot dans le cours.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Convulsions de l'enfant — Diagnostic (Accueil de l'enfant aux urgences)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un nouveau-né qui ne respire pas normalement après la naissance nécessite une évaluation et une prise en charge immédiates\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un nouveau-né qui ne respire pas ou respire mal doit être réanimé sans délai : désobstruction, séchage, ventilation au masque, oxygène.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Réanimation du nouveau-né en salle de naissance — Conduite de la réanimation\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un nourrisson de 4 mois présente une diarrhée aiguë. Quelle dose quotidienne de zinc faut-il administrer pendant 10 jours, selon le schéma enseigné ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"10 mg par jour\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"20 mg par jour\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"5 mg par jour\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"40 mg par jour\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 10 mg par jour\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Avant 6 mois : ½ comprimé de zinc à 20 mg par jour, soit 10 mg/j ; à partir de 6 mois : 1 comprimé (20 mg) par jour.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, Plan A : donner du zinc ; L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Rôles curatifs (Médicaments)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un enfant a les yeux enfoncés, boit avidement et présente un pli cutané qui s'efface lentement. Quelle classification est la plus probable ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Pas de déshydratation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Déshydratation modérée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Déshydratation sévère\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Diarrhée persistante\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Déshydratation modérée\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Yeux enfoncés, soif (boit avec avidité) et pli cutané qui s'efface lentement : au moins deux signes de la colonne « signes évidents de déshydratation », traités par le plan B.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Diagnostic de gravité (Tableau n°1 : classification)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les soins immédiats du nouveau-né, quel geste contribue directement à prévenir l'hypothermie ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Retarder le séchage\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sécher immédiatement avec un linge propre et chaud\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Donner un bain froid\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Laisser le nouveau-né découvert\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Sécher immédiatement avec un linge propre et chaud\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le séchage immédiat avec un linge propre, sec et chaud limite les pertes de chaleur par évaporation ; on place ensuite le bébé en peau à peau avec un bonnet.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Soins essentiels aux nouveau-nés — Technique de soins (0-1 minute) ; Néonatologie (module de formation), Adaptation — Thermorégulation\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est le rôle principal de la prolactine dans la lactation ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Stimuler la production du lait\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Provoquer l'éjection du lait\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Assurer la digestion du lait\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Empêcher la montée laiteuse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Stimuler la production du lait\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La prolactine commande la production du lait ; l'éjection est due à l'ocytocine.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Physiologie de la lactation (Production du lait)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un enfant présente une diarrhée sans signe de déshydratation. Quel plan convient ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Plan C\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Plan B\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Plan A\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Aucun apport oral\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Plan A\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Sans signe de déshydratation, on applique le plan A à domicile : plus de liquides, zinc, poursuite de l'alimentation, quand revenir.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, Plan A : traiter la diarrhée à domicile\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Chez un nouveau-né à terme, quel intervalle d'âge gestationnel est correct ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"28 à moins de 32 SA\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"32 à moins de 37 SA\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"37 à moins de 42 SA\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"42 à 44 SA\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 37 à moins de 42 SA\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le nouveau-né à terme naît entre 37 et 41 SA + 6 jours, c'est-à-dire de 37 à moins de 42 SA.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Nouveau-né normal — Introduction (Définition)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel signe chez un enfant diarrhéique impose une référence urgente ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Joue et boit normalement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"A trois selles molles sans autre signe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Est léthargique ou inconscient\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"A conservé son appétit\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Est léthargique ou inconscient\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Léthargique ou inconscient est un signe général de danger et un signe de déshydratation sévère : il impose une référence urgente.\\n\\nSource : Cours PCIMNE 2026, Signes généraux de dangers ; L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Diagnostic de gravité\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle hormone provoque principalement l'éjection du lait maternel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La prolactine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'insuline\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'ocytocine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La thyroxine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. L'ocytocine\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'ocytocine, libérée par la post-hypophyse lors de la succion, fait contracter les cellules autour des alvéoles et éjecte le lait.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Physiologie de la lactation (Excrétion et éjection du lait)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel indicateur anthropométrique évalue principalement l'émaciation chez l'enfant ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Taille pour âge\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Poids pour taille\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Périmètre crânien pour âge\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Âge dentaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Poids pour taille\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le rapport poids/taille mesure la malnutrition aiguë (émaciation) ; le rapport taille/âge mesure la malnutrition chronique (retard de taille).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Malnutrition de l'enfant — Diagnostic anthropométrique de la malnutrition\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les paramètres suivants, lequel mesure la croissance somatique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le poids\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le sourire social\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La marche autonome\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le langage\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Le poids\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le poids est une mesure de la croissance somatique (quantitative). Le sourire, la marche et le langage sont des acquisitions du développement psychomoteur.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Mensurations — Introduction (Définition)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle acquisition du développement est habituellement attendue vers 15 mois ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Copier un carré\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Tourner les pages d'un livre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Lire une phrase\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Nommer les jours de la semaine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Tourner les pages d'un livre\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Vers 15-18 mois, l'enfant tourne les pages d'un livre (en en sautant plusieurs). Copier un carré, lire et nommer les jours de la semaine viennent bien plus tard.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Annexes — Normes physiologiques de l'enfant (Tableau II : étapes du développement psychomoteur)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel signe est caractéristique d'un kwashiorkor ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Œdèmes bilatéraux prenant le godet\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Raideur de nuque\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Otorrhée purulente\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Cyanose isolée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Œdèmes bilatéraux prenant le godet\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le kwashiorkor associe des œdèmes fermes, indolores, bilatéraux, prenant le godet, à la bouffissure du visage et aux troubles de la peau et des cheveux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Malnutrition de l'enfant — Diagnostic positif (Kwashiorkor : examen physique)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \". Parmi les manifestations suivantes, laquelle évoque une détresse respiratoire néonatale ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Respiration calme sans effort\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Geignement expiratoire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Sommeil après la tétée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hoquet isolé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Geignement expiratoire\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le geignement expiratoire est un signe de lutte respiratoire coté dans le score de Silverman.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Détresse respiratoire du nouveau-né — Diagnostic positif (Score de Silverman) ; Néonatologie (module de formation), Détresse respiratoire néonatale — Signes cliniques\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un enfant présentant une malnutrition aiguë sévère avec anorexie et complication médicale doit être orienté vers :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une prise en charge ambulatoire sans évaluation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un programme de supplémentation simple\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une unité de stabilisation thérapeutique hospitalière\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une consultation de routine dans six mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Une unité de stabilisation thérapeutique hospitalière\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La malnutrition aiguë sévère avec complications (dont l'anorexie) est prise en charge dans une unité de nutrition thérapeutique hospitalière.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Malnutrition de l'enfant — Diagnostic anthropométrique (Classification de la malnutrition aiguë sévère)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Chez un enfant fébrile, quel examen permet de rechercher un paludisme ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Électrocardiogramme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Goutte épaisse ou test diagnostique rapide\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Audiométrie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Test de grossesse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Goutte épaisse ou test diagnostique rapide\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'examen de référence est la goutte épaisse avec frottis sanguin ; à défaut, le test de diagnostic rapide (TDR).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Paludisme de l'enfant — Diagnostic (Examen para clinique)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la démarche de soins, quelle action relève de la surveillance infirmière ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Poser seul un diagnostic médical\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Observer et noter la fréquence respiratoire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prescrire une antibiothérapie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Modifier seul une prescription\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Observer et noter la fréquence respiratoire\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Observer et noter les paramètres vitaux (fréquence respiratoire, température…) sur une fiche de surveillance fait partie du rôle infirmier. Poser un diagnostic médical ou prescrire relève du médecin.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Introduction au raisonnement clinique — Plan de soins (Interventions)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel critère traduit une bonne prise du sein ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Bouche peu ouverte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Menton éloigné du sein\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Lèvre inférieure retroussée vers l'intérieur\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Bouche largement ouverte et menton au contact du sein\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Bouche largement ouverte et menton au contact du sein\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Bonne prise du sein : bouche grande ouverte qui prend largement l'aréole, menton qui touche le sein, lèvre inférieure éversée (vers l'extérieur).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Aide et conseils à l'allaitement (Aide à l'allaitement)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est le moment recommandé pour débuter l'allaitement après une naissance sans complication ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dans la première heure\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Après six heures\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le lendemain\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Après la sortie de maternité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Dans la première heure\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La mise au sein doit être précoce : dans l'heure qui suit la naissance (entre 30 et 60 minutes de vie).\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Soins essentiels aux nouveau-nés — Technique de soins (1-60 minutes) ; L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Dix règles de l'IHAB\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel aliment est normalement recommandé de la naissance à six mois révolus ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Bouillie légère\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Lait maternel exclusivement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Eau et lait maternel\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Jus de fruits\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Lait maternel exclusivement\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'OMS et l'UNICEF recommandent l'allaitement maternel exclusif de 0 à 6 mois, sans eau ni autre aliment.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Modalités et avantages (Modalités recommandées)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'orientation d'un enfant présentant une anomalie du développement psychomoteur vers un spécialiste relève principalement :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"D'un soin de collaboration\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"D'un acte chirurgical autonome\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"D'un soin d'hygiène uniquement\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D'une mesure sans coordination\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. D'un soin de collaboration\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Orienter l'enfant vers un spécialiste se fait en lien avec le médecin et l'équipe : c'est un soin de collaboration.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Introduction au raisonnement clinique — Plan de soins (Interventions : soins en collaboration)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__40\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel élément du développement correspond à une acquisition qualitative plutôt qu'à une mesure somatique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Poids\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Taille\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Éruption dentaire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Périmètre brachial\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Éruption dentaire\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Poids, taille et périmètre brachial sont des mesures de croissance somatique. L'éruption dentaire est une étape de maturation (indicateur qualitatif). Remarque : Voir la question 10 : ce classement n'est pas écrit mot à mot dans les cours.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Mensurations — Introduction (Définition)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__41\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle acquisition est compatible avec le développement habituel vers trois ans ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"S'habiller partiellement avec aide pour les boutons\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Écrire une rédaction\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Conduire un vélo à deux roues sans aide\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Lire un journal\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. S'habiller partiellement avec aide pour les boutons\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"À 3 ans, l'enfant s'habille seul mais a besoin d'aide pour les boutons et les fermetures éclair.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Annexes — Normes physiologiques de l'enfant (Tableau II : étapes du développement psychomoteur)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \". Quel indicateur sert au suivi longitudinal de la croissance pondérale ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La température seule\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La courbe poids-pour-âge\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le groupe sanguin\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La couleur de l'iris\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. La courbe poids-pour-âge\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La courbe de poids (poids pour l'âge) du carnet de santé permet de suivre dans le temps la croissance pondérale.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Carnet de santé mère-enfant — Courbes de croissance ; Mensurations — Mesure du poids\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel élément peut justifier une évaluation du développement psychomoteur ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Sourire social adapté\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Acquisition progressive de la marche\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Régression d'une compétence déjà acquise\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Jeu adapté à l'âge\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Régression d'une compétence déjà acquise\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La perte d'une compétence déjà acquise (régression psychomotrice) est anormale et doit faire évaluer l'enfant. Les autres propositions sont des acquisitions normales. Remarque : La régression psychomotrice est citée dans le cours comme complication de plusieurs maladies, sans chapitre dédié.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Méningites bactériennes de l'enfant — Devenir (régression psychomotrice) ; Anorexie du nourrisson — Problèmes\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un nouveau-né né à 39 semaines d'aménorrhée est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Grand prématuré\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Prématuré modéré\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Post-terme\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"À terme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. À terme\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"39 SA se situe entre 37 et 41 SA + 6 jours : c'est un nouveau-né à terme.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Nouveau-né normal — Introduction (Définition)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel âge gestationnel correspond à une grande prématurité ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"28 SA à moins de 32 SA\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"34 SA à moins de 37 SA\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"37 SA à moins de 42 SA\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"42 SA et plus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 28 SA à moins de 32 SA\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Grande prématurité : 28 à 31 SA + 6 jours ; très grande prématurité : moins de 28 SA ; prématurité modérée : 32 à 36 SA + 6 jours.\\n\\nSource : Néonatologie (module de formation), Prématurité — Introduction (Classification)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les premières heures de vie, quel paramètre clinique faut-il surveiller chez le nouveau-né ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La couleur des vêtements\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La respiration\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le nombre de visiteurs\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La taille des ongles\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. La respiration\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La respiration (fréquence normale 40 à 60 cycles/min) fait partie de la surveillance initiale, avec la température, la coloration et la fréquence cardiaque.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Nouveau-né normal — Diagnostic positif (Informations à rechercher à l'examen physique)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel geste est prioritaire chez un nouveau-né qui ne respire pas après les gestes initiaux ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le peser\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Lui donner de l'eau\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Débuter une ventilation au masque selon le protocole de réanimation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Attendre trente minutes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Débuter une ventilation au masque selon le protocole de réanimation\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Si le nouveau-né ne respire pas après séchage, désobstruction et stimulation, il faut débuter sans attendre la ventilation au ballon et au masque.\\n\\nSource : Néonatologie (module de formation), Réanimation en salle de naissance — Étapes (Ventilation en pression positive) ; L'essentiel en pédiatrie tropicale (Dr Asse), Réanimation du nouveau-né — Conduite de la réanimation\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel élément fait partie du score d'Apgar ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Fréquence cardiaque\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Glycémie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Périmètre brachial\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Groupe sanguin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Fréquence cardiaque\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le score d'Apgar comporte 5 critères : fréquence cardiaque, respiration, tonus, réactivité (grimace/cri) et coloration.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Souffrance cérébrale du nouveau-né — Diagnostic (Tableau 1 : score d'Apgar) ; Cours de santé infantile L1 IDE-SFM, Examen du nouveau-né — Cotation d'Apgar\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__49\",\n       \"num\": \"50\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un nouveau-né présente à une minute : fréquence cardiaque 90/min (1 point), respiration irrégulière (1), hypotonie marquée (0), grimace à la stimulation (1) et acrocyanose (1). Quel score d'Apgar obtient-on ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"4\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"6\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 4\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"On additionne les cotations : 1 + 1 + 0 + 1 + 1 = 4 (souffrance cérébrale modérée).\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Examen du nouveau-né — Cotation d'Apgar (Tableau et interprétation)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__50\",\n       \"num\": \"51\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel conseil est adapté pour les soins du cordon ombilical du nouveau-né ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Appliquer régulièrement des poudres non prescrites\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Garder le cordon propre et sec selon le protocole\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Recouvrir de terre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Tirer sur le cordon pour accélérer sa chute\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Garder le cordon propre et sec selon le protocole\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cordon doit rester propre et sec jusqu'à la cicatrisation, avec les produits prescrits (chlorhexidine) ; les produits traditionnels, la terre ou les manipulations exposent à l'omphalite et au tétanos.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Soins ombilicaux — Après le soin (conseils à la mère) ; Néonatologie (module de formation), Accueil du nouveau-né — Naissance (les « cinq propres »)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__51\",\n       \"num\": \"52\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel signe respiratoire chez un nouveau-né nécessite une évaluation urgente ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Respiration calme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Coloration rose\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Geignement expiratoire persistant\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Tétée efficace\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Geignement expiratoire persistant\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le geignement expiratoire persistant est un signe de lutte respiratoire (détresse respiratoire) qui impose une évaluation urgente.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Détresse respiratoire du nouveau-né — Diagnostic positif (Score de Silverman)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__52\",\n       \"num\": \"53\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle situation est un facteur de risque de prématurité spontanée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Infection génito-urinaire maternelle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Allaitement précoce\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Vaccination du nouveau-né\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Peau à peau\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Infection génito-urinaire maternelle\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les infections vagino-utérines (et urinaires) font partie des causes spontanées de prématurité ; leur traitement pendant la grossesse fait partie de la prévention.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Nouveau-né prématuré — Causes de la prématurité (Causes spontanées) ; Rôles de soins préventifs\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__53\",\n       \"num\": \"54\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel examen est le plus directement indiqué pour rechercher une infection urinaire chez un enfant fébrile lorsque cette origine est suspectée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Radiographie du crâne\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"ECBU\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Électrocardiogramme\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Test de grossesse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. ECBU\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'examen cytobactériologique des urines (ECBU) est demandé devant une fièvre avec signes urinaires.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Fièvre de l'enfant — Diagnostic étiologique (Prescription d'examens)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__54\",\n       \"num\": \"55\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lors d'une convulsion en cours, quelle intervention immédiate est adaptée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Introduire une cuillère dans la bouche\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faire boire de l'eau\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Maintenir de force les membres\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Protéger l'enfant des traumatismes et surveiller sa respiration\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Protéger l'enfant des traumatismes et surveiller sa respiration\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"On installe l'enfant en position de sécurité, on assure la liberté des voies aériennes et on surveille la respiration ; on ne met rien dans la bouche, on ne fait pas boire, on ne bloque pas les membres.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Convulsions de l'enfant — Diagnostic (Accueil de l'enfant aux urgences)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__55\",\n       \"num\": \"56\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Chez un enfant qui vomit, quel soin de surveillance est adapté ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Noter les épisodes de vomissements et leur aspect\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Interrompre toute surveillance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Donner systématiquement un antiémétique sans prescription\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Faire boire de force pendant le vomissement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Noter les épisodes de vomissements et leur aspect\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La surveillance porte sur la fréquence, la quantité et l'aspect des vomissements (alimentaire, bilieux, hémorragique) et sur leur retentissement (déshydratation).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Vomissements de l'enfant — Diagnostic étiologique (Anamnèse) ; Problèmes et devenir\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__56\",\n       \"num\": \"57\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel examen est particulièrement pertinent chez un enfant fébrile présentant une suspicion de paludisme\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Goutte épaisse ou test diagnostique rapide selon protocole\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Test de grossesse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Audiométrie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Radiographie dentaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Goutte épaisse ou test diagnostique rapide selon protocole\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La goutte épaisse et le frottis sanguin, ou à défaut le TDR, confirment le paludisme.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Paludisme de l'enfant — Diagnostic (Examen para clinique)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__57\",\n       \"num\": \"58\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Chez un enfant présentant des vomissements, quel soin relève directement de la surveillance infirmière ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Prescrire seul un antiémétique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ignorer les pertes hydriques\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Noter la fréquence des vomissements et l'état d'hydratation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Arrêter systématiquement tout liquide pendant 24 heures\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Noter la fréquence des vomissements et l'état d'hydratation\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Noter la fréquence des vomissements et surveiller l'état d'hydratation permet de dépister la déshydratation, principale complication des vomissements.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Vomissements de l'enfant — Problèmes et devenir (Problèmes : déshydratation)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__58\",\n       \"num\": \"59\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un enfant de 15 mois présente une fièvre élevée, refuse de boire et paraît léthargique. Quelle décision est prioritaire ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Revoir dans un mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Conseiller seulement un bain\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Laisser repartir sans surveillance\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Évaluer et référer en urgence\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Évaluer et référer en urgence\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Incapacité de boire et léthargie sont des signes généraux de danger : l'enfant doit être évalué et référé en urgence après les premiers soins.\\n\\nSource : Cours PCIMNE 2026, Signes généraux de dangers ; Différentes bandes de la PCIMNE (rose : référence d'urgence)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j4-idesfm__59\",\n       \"num\": \"60\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la démarche de soins, quelle formulation constitue un objectif mesurable de surveillance d'un enfant fébrile ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'enfant ira mieux bientôt\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La température sera réévaluée et documentée dans l'heure suivant les soins prescrits\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'enfant ne sera plus jamais malade\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La famille sera toujours satisfaite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. La température sera réévaluée et documentée dans l'heure suivant les soins prescrits\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un objectif de soins doit être précis, mesurable et daté : la température réévaluée et notée dans l'heure répond à ces critères.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Introduction au raisonnement clinique — Plan de soins (Objectifs de soins)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
